cd /home/user/fortress-stringmembers && wait_for () {
    local n=0 max=${2:-270}
    case "$max" in ''|*[!0-9]*) max=270 ;; esac ; [ "$max" -gt 270 ] && max=270
    while ! grep -q '^EXIT=' "$1" 2>/dev/null ; do
        sleep 5 ; n=$((n+5))
        [ "$n" -ge "$max" ] && { echo "still running after ${n}s" ; return 1 ; }
    done
    grep -n '^BUILD \|^Total time:\|^OK (\|^FAILURES!!!\|^Tests run:\|^EXIT=' "$1"
}
wait_for tmp/rung-string-members/count-run.txt; date -u +%H:%M:%S; tail -5 tmp/rung-string-members/count-run.txt

